func decodeLiveCommandResponse(resp *http.Response) (res *LiveCommandNoContent, _ error) {
	switch resp.StatusCode {
	case 204:
		// Code 204.
		return &LiveCommandNoContent{}, nil
	}
	return res, validate.UnexpectedStatusCodeWithResponse(resp)
}

